package org.opensmartisanos.ui.widget;import android.content.Context;import android.util.AttributeSet;import android.view.Gravity;import android.view.LayoutInflater;import android.view.View;import android.widget.LinearLayout;import android.widget.TextView;import org.opensmartisanos.ui.R;
public class SmartisanSnackbarWithButton extends LinearLayout{private final TextView action,message;private View.OnClickListener listener;public SmartisanSnackbarWithButton(Context c){this(c,null);}public SmartisanSnackbarWithButton(Context c,AttributeSet a){this(c,a,0);}public SmartisanSnackbarWithButton(Context c,AttributeSet a,int s){super(c,a,s);LayoutInflater.from(c).inflate(R.layout.smartisan_rom_snackbar_with_btn_layout,this,true);setGravity(Gravity.CENTER_VERTICAL);action=findViewById(R.id.smartisan_rom_action_btn);message=findViewById(android.R.id.message);action.setOnClickListener(v->{if(listener!=null)listener.onClick(v);});}public void setMessage(CharSequence v){message.setText(v);}public void setMessage(int r){message.setText(r);}public void setActionText(CharSequence v){action.setText(v);}public void setActionText(int r){action.setText(r);}public void setActionListener(View.OnClickListener l){listener=l;}}
